By \cref{def:repbudget}, it suffices to provide a finite $n$ and model-pair sampling distribution $\mathcal{C}$ under which $\mathcal{A}_{\mathrm{TRR}}$ succeeds uniformly over every problem instance with minimum average utility gap $\Delta \geq \varepsilon$. Let $m_0$ be the reference model used by $\mathcal{A}_{\mathrm{TRR}}$. Define 
\[
\mathcal{C} := \mathrm{Unif}(\{\{m,m_0\}:m \in \mathcal{M} \setminus m_0\})
\]
Fix $m \neq m_0$. For each context $j \in I_m$, we can write 
\[
u_{i^j}(t^j,m) - u_{i^j}(t^j,m_0) = \frac{1}{\beta}\log \frac{p_j(m)}{1-p_j(m)}=\frac{1}{\beta} \sum_{k=1}^{\infty} \frac{p_j(m)^k - (1 - p_j(m))^k}{k},
\]
where $p_j(m) = \sigma(\beta(u_{i^j}(t^j,m) - u_{i^j}(t^j,m_0)))$ is the BT win probability for $m$ over $m_0$.
Now, consider the following statistic:
\[
\widetilde{Z}_j(m) = \frac{1}{\beta}\sum_{k=1}^{K_j}
\frac{
\prod_{r=1}^{k} y_r^j
-
\prod_{r=1}^{k} (1-y_r^j)
}{
k \mathbb{P}(K_j \geq k)
}.
\]
Now, observe that 
\[
\mathbb{E}\left[\prod_{r=1}^{k} y_r^j|K_j,W_j(m) \right] = \frac{\binom{W_j(m)}{k}}{\binom{K_j}{k}} \qquad \text{and} \qquad \mathbb{E}\left[\prod_{r=1}^{k} (1-y_r^j)|K_j,W_j(m) \right] = \frac{\binom{K_j-W_j(m)}{k}}{\binom{K_j}{k}}.
\]
It follows that the statistic we use for our estimator $Z_j(m)$ can be written as
\[
Z_j(m) = \mathbb{E}[\widetilde{Z}_j(m)|K_j,W_j(m)].
\]
We first compute the expectation of $Z_j(m)$, conditional on the context. Observe that by the Law of Total Expectation, $\mathbb{E}[Z_j(m)|i^j,t^j,j \in I_m] = \mathbb{E}[\widetilde{Z}_j(m)|i^j,t^j,j\in I_m]$. Then, we can compute
\begin{align*}
\mathbb{E}[\widetilde{Z}_j(m)|i^j,t^j,j\in I_m] &= \sum_{k=1}^d \mathbb{P}(K_j=k)\mathbb{E}[\widetilde{Z}_j(m)|i^j,t^j,j\in I_m,K_j=k] \\
&=\frac{1}{\beta}
\sum_{k=1}^{d}
\mathbb{P}(K_j=k)
\sum_{\ell=1}^{k}
\frac{
p_j(m)^\ell-(1-p_j(m))^\ell
}{
\ell \mathbb{P}(K_j \geq \ell)
}
\\
&=
\frac{1}{\beta}
\sum_{\ell=1}^{d}
\frac{
p_j(m)^\ell-(1-p_j(m))^\ell
}{
\ell \mathbb{P}(K_j \geq \ell)
}
\sum_{k=\ell}^{d}
\mathbb{P}(K_j=k) \\
&=
\frac{1}{\beta}
\sum_{\ell=1}^{d}
\frac{
p_j(m)^\ell-(1-p_j(m))^\ell
}{
\ell \mathbb{P}(K_j \geq \ell)}\mathbb{P}(K_j\geq \ell) \\
&=\frac{1}{\beta}
\sum_{\ell=1}^{d}
\frac{
p_j(m)^\ell-(1-p_j(m))^\ell
}{
\ell}, \\
\end{align*}
Thus, the conditional expectation of $Z_j(m)$ is the series representation of $u_{i^j}(t^j,m) - u_{i^j}(t^j,m_0)$, truncated at $d$. We then bound the bias as follows: 
\begin{align*}
|\mathbb{E}[Z_j(m)|i^j,t^j,j \in I_m]-(u_{i^j}(t^j,m) - u_{i^j}(t^j,m_0))| &\leq \frac{1}{\beta}\sum_{k>d}\frac{|p_j(m)^k-(1-p_j(m))^k|}{k} \\
\intertext{Since $p_j(m),1-p_j(m) \leq \sigma(\beta)$, this gives,}
&\leq \frac{1}{\beta}\sum_{k > d}\frac{2\sigma(\beta)^k}{k} \\
&\leq \frac{2\sigma(\beta)^{d+1}}{\beta(d+1)(1-\sigma(\beta))}.
\end{align*}
Now, if we choose
\[
d \geq \frac{\log \frac{16}{\beta(1-\sigma(\beta))\varepsilon}}{\log \frac{1}{\sigma(\beta)}}=O\left(\log \frac{1}{\varepsilon}\right),
\]
we get 
\[
\frac{2\sigma(\beta)^{d+1}}{\beta(d+1)(1-\sigma(\beta))} \leq \frac{\varepsilon}{8}.
\]

Since the model pair is sampled from $\mathcal{C}$, independently of the context,
\[
\mathbb{E}[u_{i^j}(t^j,m) - u_{i^j}(t^j,m_0)] = \overline{u}(m) -\overline{u}(m_0).
\]
Then, averaging over contexts gives
\[
|\mathbb{E}[Z_j(m)|j \in I_m] - (\overline{u}(m) -\overline{u}(m_0)) \leq \frac{\varepsilon}{8}.
\]
We have controlled the bias of $Z_j(m)$. It remains to control the variance and bound $|Z_j(m)|$ before completing the proof. For the variance, observe that by Jensen's Inequality 
\[
\mathbb{E}[Z_j(m)^2|i^j,t^j,j \in I_m] \leq \mathbb{E}\left[\widetilde{Z}_j(m)^2|i^j,t^j, j \in I_m \right].
\]
Then, it suffices to bound the variance of $\widetilde{Z}_j(m)$ by bounding its second moment. First, we rewrite $\widetilde{Z}_j(m)$ as

\[
\widetilde{Z}_j(m)
=
\frac{1}{\beta}
\sum_{k=1}^{K_j}
\frac{
\prod_{r=1}^k y_r^j
-
\prod_{r=1}^k (1-y_r^j)
}{
\rho^{k-1}
}
=
\frac{1}{\beta}
\sum_{k=1}^{d}
\mathbf 1\{K_j\ge k\}
\frac{
\prod_{r=1}^k y_r^j
-
\prod_{r=1}^k (1-y_r^j)
}{
\rho^{k-1}
}.
\]

Then, applying Minkowski's Inequality, we get
\begin{align*}
\sqrt{
\mathbb{E}\!\left[\widetilde{Z}_{j}(m)^2 \mid i^j,t^j,j \in I_m \right]
}
&\le
\frac{1}{\beta}
\sum_{k=1}^d
\frac{1}{\rho^{k-1}}
\sqrt{
\mathbb{E}\!\left[
\mathbf 1\{K_j\ge k\}
\left(
\prod_{r=1}^k y_r^j
-
\prod_{r=1}^k(1-y_r^j)
\right)^2
\middle|i^j,t^j,j \in I_m
\right]
}\\
\intertext{Since both products above cannot simultaneously equal 1,}
&=
\frac{1}{\beta}
\sum_{k=1}^d
\frac{
\sqrt{
\mathbb{P}(K_j \geq k)\left(p_j(m)^k+(1-p_j(m))^k\right)
}
}{
\rho^{k-1}
}\\
\intertext{Using $p_j(m),1-p_j(m) \leq \sigma(\beta)$ and plugging in $\mathbb{P}(K_j \geq k)= \frac{\rho^{k-1}}{k}$ gives}
&\le
\frac{\sqrt{2\rho}}{\beta}
\sum_{k=1}^d
\frac{1}{\sqrt{k}}
\left(
\frac{\sigma(\beta)}{\rho}
\right)^{k/2}\\
&\le
\frac{\sqrt{2\rho}}{\beta}
\sum_{k=1}^{\infty}
\frac{1}{\sqrt{k}}
\left(
\frac{\sigma(\beta)}{\rho}
\right)^{k/2}
=:V_\beta = O(1)<\infty.
\end{align*}
In the final line, we know the series converges because $\rho > \sigma(\beta)$. It follows that $\mathbb{E}[\widetilde{Z}_j(m)^2|j \in I_m] \leq V_{\beta}^2$.

Next, we obtain a bound on $|Z_j(m)|$. Note that boundedness of $|Z_j(m)|$ is immediate from the fact that $K_j$ is truncated at $d$. This would be sufficient for the remainder of the proof. However, in the interest of actually quantifying the number of sampled contexts that we need, we explicitly bound $|Z_j(m)|$.  
\[
|Z_j(m)| \leq \frac{1}{\beta}\sum_{k=1}^{K_j} \frac{1}{\rho^{k-1}} \leq \frac{1}{\beta}\sum_{k=1}^d\frac{1}{\rho^{k-1}} \leq C_{\beta}\rho^{-d}
\]
for some constant $C_{\beta}$. Then, since $d = O\left(\log \frac{1}{\varepsilon}\right)$ and $\sigma(\beta) < \rho < 1$, there exists an exponent $a_{\beta} \in (0,1)$ such that 
\[
\rho^{-d} \leq C_{\beta}\varepsilon^{-a_{\beta}}.
\]


We can now apply Bernstein's Inequality to 
\[
\widehat{g}_{\mathrm{TRR}}(m) = \frac{1}{|I_m|}\sum_{j \in I_m} Z_j(m),
\]
obtaining that 
\[
\mathbb{P}\left(|\widehat{g}_{\mathrm{TRR}}(m)-\mathbb{E}[{Z_j(m)}|j \in I_m]| > \frac{\varepsilon}{8}|I_m \right) \leq 2\exp(-c_{\beta}|I_m|\varepsilon^2)
\]
for some constant $c_\beta > 0$. By \cref{lem:controlobs}, taking
\[
n = O\left(\frac{|\mathcal{M}|}{\varepsilon^2}\log\frac{|\mathcal{M}|}{\delta} \right)
\]
gives that with probability at least $1-\delta/2$,
\[
|I_m| \geq \frac{1}{c_\beta \varepsilon^2}\log \frac{4|\mathcal{M}|}{\delta}
\]
simultaneously for all $m \neq m_0$. 
Conditioning on this event and taking a union bound over $m \neq m_0$ gives that with probability at least $1-\delta/2$
\[|\widehat{g}_{\mathrm{TRR}}(m)-\mathbb{E}[{Z_j(m)}|j \in I_m]| \leq \frac{\varepsilon}{8}\]
simultaneously for all $m \neq m_0$. Combining this with the bound on the bias of $Z_j(m)$, we obtain that 
\[
|\widehat{g}_{\mathrm{TRR}}(m) - (\overline{u}(m) - \overline{u}(m_0))| \leq \frac{\varepsilon}{4}.
\]
Take any pair of models $m,m'$. Triangle inequality then implies that 
\[
|(\widehat{g}_{\mathrm{TRR}}(m) - \widehat{g}_{\mathrm{TRR}}(m')) - (\overline{u}(m) - \overline{u}(m'))| \leq \frac{\varepsilon}{2}.
\]
It follows that ranking under $\widehat{g}_{\mathrm{TRR}}(m)$, which is the procedure that $\mathcal{A}_{\mathrm{TRR}}$ uses, preserves the ranking under average utility. We conclude the proof by calculating the expectation of $K_j$. 
\[
\mathbb{E}[K_j] = \sum_{k=1}^d \mathbb{P}(K_j\geq k) = \sum_{k=1}^d \frac{\rho^{k-1}}{k} \leq \frac{1}{\rho}\sum_{k=1}^{\infty} \frac{\rho^k}{k} = \frac{1}{\rho}\log \frac{1}{1-\rho} = O(1).
\]
